SELECT DISTINCT q.article_ref AS artigo_ce_sem_ligacao
FROM questions q
WHERE q.external_id REGEXP '^inatro-e[0-9]{2}-q[0-9]{2}$'
  AND q.article_ref IS NOT NULL
  AND q.article_id IS NULL;
